// Generates crates/sirene-core/src/math/metrics_data.rs: KaTeX's per-glyph font metrics
// (spec/latex-math.md, LMATH-12, `metrics`). Development tool: the generated file is checked in.
//
// Setup (once): the KaTeX checkout described in scripts/katex-fixtures.mjs, at tag v0.19.1.
// Run:
//   node --no-warnings scripts/katex-metrics.mjs
//
// The source is KaTeX's `src/fontMetricsData.js`, itself generated from TeX font metric files
// and the KaTeX fonts (spec/latex-resources.md, LRES-T7b). Each face's glyphs are sorted by
// code point; each row is depth, height, italic correction, skew, and width in em. Adapted from
// KaTeX, MIT licensed, Copyright (c) 2013-2020 Khan Academy and other contributors; see
// THIRD-PARTY-NOTICES.

import { writeFileSync } from "node:fs";

const { default: metrics } = await import(new URL("../local/katex/src/fontMetricsData.js", import.meta.url));

// The Rust name of each face, from KaTeX's font name (`Main-Regular` -> `MainRegular`).
const faces = Object.keys(metrics).sort();
const variant = (face) => face.replace("-", "").replace("AMS", "Ams");

let glyphs = 0;
let tables = "";
for (const face of faces) {
  const rows = Object.entries(metrics[face])
    .map(([cp, m]) => {
      if (m.length !== 5 || m.some((x) => typeof x !== "number")) throw new Error(`bad row ${face} ${cp}`);
      return [Number(cp), m];
    })
    .sort((a, b) => a[0] - b[0]);
  glyphs += rows.length;
  tables += `\n/// The glyphs of ${face}.\nconst ${variant(face).toUpperCase()}: &[Glyph] = &[\n`;
  for (const [cp, m] of rows) {
    tables += `    (0x${cp.toString(16)}, [${m.map((x) => (Number.isInteger(x) ? `${x}.0` : `${x}`)).join(", ")}]),\n`;
  }
  tables += "];\n";
}

const out = `// Generated by scripts/katex-metrics.mjs from KaTeX 0.19.1. Do not edit.
// Adapted from KaTeX, MIT licensed, Copyright (c) 2013-2020 Khan Academy and other contributors;
// see THIRD-PARTY-NOTICES.
// Measured widths, some near a constant such as pi/4 by chance.
#![allow(clippy::approx_constant)]

/// A code point and its depth, height, italic correction, skew, and width in em.
pub(super) type Glyph = (u32, [f64; 5]);

/// The KaTeX font faces that have metrics.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Face {
${faces.map((f) => `    ${variant(f)},`).join("\n")}
}

impl Face {
    /// Every face, in the order of the enum.
    pub(crate) const ALL: [Face; ${faces.length}] = [
${faces.map((f) => `        Face::${variant(f)},`).join("\n")}
    ];

    /// KaTeX's name for the face (\`Main-Regular\`).
    pub(crate) fn name(self) -> &'static str {
        match self {
${faces.map((f) => `            Face::${variant(f)} => "${f}",`).join("\n")}
        }
    }

    /// The face's glyphs, sorted by code point.
    pub(super) fn glyphs(self) -> &'static [Glyph] {
        match self {
${faces.map((f) => `            Face::${variant(f)} => ${variant(f).toUpperCase()},`).join("\n")}
        }
    }
}
${tables}`;
writeFileSync(new URL("../crates/sirene-core/src/math/metrics_data.rs", import.meta.url), out);
console.log(`${faces.length} faces, ${glyphs} glyphs`);
